const t=[{id:"a2_1",level:"A2",topic:"travel",title:"My Trip to Ho Chi Minh City",titleVi:"Chuyến Đi Thành Phố Hồ Chí Minh",illustrationEmoji:"🏙️",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: chuyến đi thành phố hồ chí minh.",englishText:"Last year, I visited Ho Chi Minh City with my family. It is a big and **busy** city. There are many **tall** buildings and a lot of **traffic**. We visited the **Ben Thanh Market**. I bought some **souvenirs** for my friends. We also went to the **War Remnants Museum**. I learned about the **history** of Vietnam. The food in Sai Gon was **amazing**. I tried banh mi and com tam. The people are very **friendly**. I want to come back one day.",vietnameseText:"Năm ngoái, tôi đã đến thăm Thành phố Hồ Chí Minh cùng gia đình. Đó là một thành phố lớn và **bận rộn**. Có nhiều tòa nhà **cao** và **giao thông** đông đúc. Chúng tôi đã tham quan **Chợ Bến Thành**. Tôi đã mua một số **quà lưu niệm** cho bạn bè. Chúng tôi cũng đã đến **Bảo tàng Chứng tích Chiến tranh**. Tôi đã học được về **lịch sử** của Việt Nam. Đồ ăn ở Sài Gòn thật **tuyệt vời**. Tôi đã thử bánh mì và cơm tấm. Người dân rất **thân thiện**. Tôi muốn quay lại một ngày nào đó.",vocabularyFocus:[{word:"busy",vi:"bận rộn",example:""},{word:"tall",vi:"cao",example:""},{word:"traffic",vi:"giao thông",example:""},{word:"souvenirs",vi:"quà lưu niệm",example:""},{word:"history",vi:"lịch sử",example:""},{word:"amazing",vi:"tuyệt vời",example:""},{word:"friendly",vi:"thân thiện",example:""},{word:"visit",vi:"thăm",example:""}],phrases:[{en:"I visited Ho Chi Minh City with my family.",vi:"Tôi đã đến thăm Thành phố Hồ Chí Minh cùng gia đình."},{en:"It is a big and busy city.",vi:"Đó là một thành phố lớn và bận rộn."},{en:"I bought some souvenirs for my friends.",vi:"Tôi đã mua một số quà lưu niệm cho bạn bè."},{en:"The food in Sai Gon was amazing.",vi:"Đồ ăn ở Sài Gòn thật tuyệt vời."},{en:"I want to come back one day.",vi:"Tôi muốn quay lại một ngày nào đó."}],comprehensionQuestions:[{question:"Where did the writer go last year?",options:["Ha Noi","Ho Chi Minh City","Da Nang","Hue"],correct:1},{question:"What did the writer buy at Ben Thanh Market?",options:["Clothes","Food","Souvenirs","Books"],correct:2},{question:"Which museum did the writer visit?",options:["History Museum","War Remnants Museum","Fine Arts Museum","Women Museum"],correct:1},{question:"What food did the writer try?",options:["Pho and bun cha","Banh mi and com tam","Spring rolls","Sticky rice"],correct:1},{question:"How would the writer describe the people?",options:["Quiet","Friendly","Shy","Serious"],correct:1}],answers:[1,2,1,1,1],answerExplanationVi:"1. Người viết đã đến Thành phố Hồ Chí Minh vào năm ngoái. 2. Người viết đã mua quà lưu niệm ở Chợ Bến Thành. 3. Người viết đã thăm Bảo tàng Chứng tích Chiến tranh. 4. Người viết đã thử bánh mì và cơm tấm. 5. Người viết miêu tả người dân rất thân thiện.",discussionQuestions:["Bạn đã từng đến Thành phố Hồ Chí Minh chưa? Bạn thích điều gì nhất ở đó?","Theo bạn, thành phố nào ở Việt Nam thú vị nhất? Tại sao?","Bạn thường mua quà lưu niệm gì khi đi du lịch?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I visited Ho Chi Minh City with my family.","It is a big and busy city.","We visited the Ben Thanh Market.","I learned about the history of Vietnam.","The food in Sai Gon was amazing."]},{id:"a2_2",level:"A2",topic:"food",title:"Cooking with My Mother",titleVi:"Nấu Ăn Cùng Mẹ",illustrationEmoji:"🍳",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: nấu ăn cùng mẹ.",englishText:"I love cooking with my **mother**. Every Sunday, we cook together. Last week, we made **canh chua** – a sour fish soup. First, we **prepared** the ingredients: fish, tomatoes, and pineapple. Then we **boiled** water and added the fish. Mother said I **chopped** the vegetables well. The soup **tasted** delicious. My father **ate** three bowls! Cooking with my mother is **fun**. I learn many **recipes** from her.",vietnameseText:"Tôi thích nấu ăn cùng **mẹ** tôi. Mỗi Chủ Nhật, chúng tôi nấu ăn cùng nhau. Tuần trước, chúng tôi đã làm **canh chua** – một món súp cá chua. Đầu tiên, chúng tôi **chuẩn bị** nguyên liệu: cá, cà chua và dứa. Sau đó chúng tôi **luộc** nước và cho cá vào. Mẹ nói tôi **thái** rau rất tốt. Súp có **vị** rất ngon. Bố tôi đã **ăn** ba bát! Nấu ăn cùng mẹ thật **vui**. Tôi học được nhiều **công thức** từ mẹ.",vocabularyFocus:[{word:"mother",vi:"mẹ",example:""},{word:"prepared",vi:"chuẩn bị",example:""},{word:"boiled",vi:"luộc",example:""},{word:"chopped",vi:"thái",example:""},{word:"tasted",vi:"có vị",example:""},{word:"fun",vi:"vui",example:""},{word:"recipes",vi:"công thức",example:""},{word:"canh chua",vi:"canh chua",example:""}],phrases:[{en:"I love cooking with my mother.",vi:"Tôi thích nấu ăn cùng mẹ tôi."},{en:"We made canh chua – a sour fish soup.",vi:"Chúng tôi đã làm canh chua – một món súp cá chua."},{en:"First, we prepared the ingredients.",vi:"Đầu tiên, chúng tôi chuẩn bị nguyên liệu."},{en:"The soup tasted delicious.",vi:"Súp có vị rất ngon."},{en:"I learn many recipes from her.",vi:"Tôi học được nhiều công thức từ mẹ."}],comprehensionQuestions:[{question:"When does the writer cook with mother?",options:["Every Saturday","Every Sunday","Every Monday","Every Friday"],correct:1},{question:"What dish did they make last week?",options:["Pho","Canh chua","Spring rolls","Sticky rice"],correct:1},{question:"Who chopped the vegetables?",options:["Father","Mother","The writer","Sister"],correct:2},{question:"How many bowls of soup did father eat?",options:["One","Two","Three","Four"],correct:2},{question:"How does the writer feel about cooking with mother?",options:["Bored","Fun","Tired","Difficult"],correct:1}],answers:[1,1,2,2,1],answerExplanationVi:"1. Người viết nấu ăn cùng mẹ vào mỗi Chủ Nhật. 2. Tuần trước họ đã làm canh chua. 3. Mẹ nói người viết thái rau tốt, nên người viết đã thái rau. 4. Bố đã ăn ba bát súp. 5. Người viết thấy nấu ăn cùng mẹ thật vui.",discussionQuestions:["Bạn có thích nấu ăn không? Món ăn yêu thích của bạn là gì?","Bạn thường nấu ăn cùng ai trong gia đình?","Theo bạn, tại sao nấu ăn là một kỹ năng quan trọng?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I love cooking with my mother.","Last week, we made canh chua.","First, we prepared the ingredients.","The soup tasted delicious.","I learn many recipes from her."]},{id:"a2_3",level:"A2",topic:"school",title:"My School Festival",titleVi:"Lễ Hội Trường Tôi",illustrationEmoji:"🎪",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: lễ hội trường tôi.",englishText:"Our school had a big **festival** last month. We decorated the **hall** with balloons and flowers. There were many **activities**: singing, dancing, and games. My class **performed** a play about Vietnamese history. I **played** the role of a farmer. We also had a **food fair**. My mother made spring rolls for our stall. The festival was **wonderful**. Everyone had a great time.",vietnameseText:"Trường chúng tôi đã có một **lễ hội** lớn vào tháng trước. Chúng tôi đã trang trí **hội trường** với bóng bay và hoa. Có nhiều **hoạt động**: ca hát, nhảy múa và trò chơi. Lớp tôi đã **biểu diễn** một vở kịch về lịch sử Việt Nam. Tôi đã **đóng** vai một người nông dân. Chúng tôi cũng có một **hội chợ ẩm thực**. Mẹ tôi đã làm nem rán cho gian hàng của chúng tôi. Lễ hội thật **tuyệt vời**. Mọi người đều có khoảng thời gian tuyệt vời.",vocabularyFocus:[{word:"festival",vi:"lễ hội",example:""},{word:"hall",vi:"hội trường",example:""},{word:"activities",vi:"hoạt động",example:""},{word:"performed",vi:"biểu diễn",example:""},{word:"played",vi:"đóng",example:""},{word:"food fair",vi:"hội chợ ẩm thực",example:""},{word:"wonderful",vi:"tuyệt vời",example:""},{word:"decorated",vi:"trang trí",example:""}],phrases:[{en:"Our school had a big festival last month.",vi:"Trường chúng tôi đã có một lễ hội lớn vào tháng trước."},{en:"We decorated the hall with balloons and flowers.",vi:"Chúng tôi đã trang trí hội trường với bóng bay và hoa."},{en:"My class performed a play about Vietnamese history.",vi:"Lớp tôi đã biểu diễn một vở kịch về lịch sử Việt Nam."},{en:"We also had a food fair.",vi:"Chúng tôi cũng có một hội chợ ẩm thực."},{en:"The festival was wonderful.",vi:"Lễ hội thật tuyệt vời."}],comprehensionQuestions:[{question:"When did the school festival happen?",options:["Last week","Last month","Last year","Yesterday"],correct:1},{question:"How did they decorate the hall?",options:["With lights and paper","With balloons and flowers","With paintings","With flags"],correct:1},{question:"What did the writer class perform?",options:["A dance","A song","A play","A magic show"],correct:2},{question:"What role did the writer play?",options:["A king","A farmer","A teacher","A soldier"],correct:1},{question:"What did the mother make for the food fair?",options:["Cakes","Spring rolls","Noodles","Rice"],correct:1}],answers:[1,1,2,1,1],answerExplanationVi:"1. Lễ hội trường diễn ra vào tháng trước. 2. Họ trang trí hội trường bằng bóng bay và hoa. 3. Lớp người viết đã biểu diễn một vở kịch. 4. Người viết đóng vai một người nông dân. 5. Mẹ người viết đã làm nem rán cho hội chợ ẩm thực.",discussionQuestions:["Trường bạn có tổ chức lễ hội không? Bạn thích hoạt động nào nhất?","Bạn đã bao giờ tham gia biểu diễn văn nghệ chưa?","Theo bạn, lễ hội trường học có ý nghĩa gì?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["Our school had a big festival last month.","We decorated the hall with balloons and flowers.","My class performed a play about Vietnamese history.","The festival was wonderful.","Everyone had a great time."]},{id:"a2_4",level:"A2",topic:"work",title:"A Busy Day at the Shop",titleVi:"Một Ngày Bận Rộn Ở Cửa Hàng",illustrationEmoji:"🏪",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: một ngày bận rộn ở cửa hàng.",englishText:"My family owns a small **shop** that sells stationery. Last Saturday, I **helped** my parents at the shop. The morning was very **busy**. Many **customers** came to buy notebooks and pens. I **counted** the money and gave **change**. In the afternoon, I **arranged** the products on the shelves. I was **tired** but happy. Working at the shop taught me to be **responsible**.",vietnameseText:"Gia đình tôi có một **cửa hàng** nhỏ bán văn phòng phẩm. Thứ Bảy tuần trước, tôi đã **giúp** bố mẹ ở cửa hàng. Buổi sáng rất **bận rộn**. Nhiều **khách hàng** đến mua vở và bút. Tôi đã **đếm** tiền và trả **tiền thừa**. Buổi chiều, tôi **sắp xếp** sản phẩm lên kệ. Tôi **mệt** nhưng vui. Làm việc ở cửa hàng dạy tôi trở nên **có trách nhiệm**.",vocabularyFocus:[{word:"shop",vi:"cửa hàng",example:""},{word:"helped",vi:"giúp",example:""},{word:"busy",vi:"bận rộn",example:""},{word:"customers",vi:"khách hàng",example:""},{word:"counted",vi:"đếm",example:""},{word:"change",vi:"tiền thừa",example:""},{word:"arranged",vi:"sắp xếp",example:""},{word:"responsible",vi:"có trách nhiệm",example:""}],phrases:[{en:"My family owns a small shop that sells stationery.",vi:"Gia đình tôi có một cửa hàng nhỏ bán văn phòng phẩm."},{en:"Last Saturday, I helped my parents at the shop.",vi:"Thứ Bảy tuần trước, tôi đã giúp bố mẹ ở cửa hàng."},{en:"Many customers came to buy notebooks and pens.",vi:"Nhiều khách hàng đến mua vở và bút."},{en:"I counted the money and gave change.",vi:"Tôi đã đếm tiền và trả tiền thừa."},{en:"Working at the shop taught me to be responsible.",vi:"Làm việc ở cửa hàng dạy tôi trở nên có trách nhiệm."}],comprehensionQuestions:[{question:"What does the family shop sell?",options:["Clothes","Stationery","Food","Toys"],correct:1},{question:"When did the writer help at the shop?",options:["Last Monday","Last Friday","Last Saturday","Last Sunday"],correct:2},{question:"How was the morning at the shop?",options:["Quiet","Busy","Boring","Slow"],correct:1},{question:"What did the writer do in the afternoon?",options:["Counted money","Talked to customers","Arranged products","Cleaned the shop"],correct:2},{question:"How did the writer feel after working?",options:["Angry","Tired but happy","Excited","Disappointed"],correct:1}],answers:[1,2,1,2,1],answerExplanationVi:"1. Cửa hàng gia đình bán văn phòng phẩm. 2. Người viết đã giúp vào thứ Bảy tuần trước. 3. Buổi sáng rất bận rộn. 4. Buổi chiều người viết sắp xếp sản phẩm lên kệ. 5. Người viết mệt nhưng vui.",discussionQuestions:["Bạn đã bao giờ làm việc trong cửa hàng của gia đình chưa?","Theo bạn, làm việc có dạy cho bạn điều gì?","Bạn nghĩ thế nào về việc giúp đỡ bố mẹ trong công việc?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My family owns a small shop that sells stationery.","The morning was very busy.","Many customers came to buy notebooks and pens.","I counted the money and gave change.","Working at the shop taught me to be responsible."]},{id:"a2_5",level:"A2",topic:"daily life",title:"My Weekend Plans",titleVi:"Kế Hoạch Cuối Tuần Của Tôi",illustrationEmoji:"🗓️",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: kế hoạch cuối tuần của tôi.",englishText:`I have some **exciting** plans for this weekend. On Saturday morning, I will **visit** my grandmother in the countryside. She lives about 20 kilometers from my house. I will go there by **bus**. My grandmother always cooks **delicious** meals for me. I will help her water the plants in the garden.

On Saturday afternoon, I will **meet** my friends at the park. We will play soccer **together**. After that, we plan to watch a new movie at the **cinema**. Everyone is talking about it. I am really looking forward to it.

On Sunday, I will **stay** at home and complete my homework. I have a math test on Monday, so I need to **prepare** carefully. In the evening, my family will have dinner **together**. I love weekends because I can relax and do many interesting things.`,vietnameseText:`Tôi có một vài kế hoạch **thú vị** cho cuối tuần này. Sáng thứ Bảy, tôi sẽ **thăm** bà tôi ở vùng nông thôn. Bà sống cách nhà tôi khoảng 20 cây số. Tôi sẽ đến đó bằng xe **buýt**. Bà tôi luôn nấu những bữa ăn **ngon** cho tôi. Tôi sẽ giúp bà tưới cây trong vườn.

Chiều thứ Bảy, tôi sẽ **gặp** bạn bè ở công viên. Chúng tôi sẽ chơi bóng đá **cùng nhau**. Sau đó, chúng tôi dự định xem một bộ phim mới ở **rạp chiếu phim**. Mọi người đều đang bàn tán về nó. Tôi thực sự mong chờ điều đó.

Chủ Nhật, tôi sẽ **ở** nhà và hoàn thành bài tập về nhà. Tôi có bài kiểm tra toán vào thứ Hai, vì vậy tôi cần **chuẩn bị** cẩn thận. Buổi tối, gia đình tôi sẽ ăn tối **cùng nhau**. Tôi yêu cuối tuần vì tôi có thể thư giãn và làm nhiều điều thú vị.`,vocabularyFocus:[{word:"exciting",vi:"thú vị",example:""},{word:"visit",vi:"thăm",example:""},{word:"bus",vi:"xe buýt",example:""},{word:"delicious",vi:"ngon",example:""},{word:"meet",vi:"gặp",example:""},{word:"together",vi:"cùng nhau",example:""},{word:"cinema",vi:"rạp chiếu phim",example:""},{word:"prepare",vi:"chuẩn bị",example:""}],phrases:[{en:"I have some exciting plans for this weekend.",vi:"Tôi có một vài kế hoạch thú vị cho cuối tuần này."},{en:"I will visit my grandmother in the countryside.",vi:"Tôi sẽ thăm bà tôi ở vùng nông thôn."},{en:"I will go there by bus.",vi:"Tôi sẽ đến đó bằng xe buýt."},{en:"We will play soccer together.",vi:"Chúng tôi sẽ chơi bóng đá cùng nhau."},{en:"I love weekends because I can relax.",vi:"Tôi yêu cuối tuần vì tôi có thể thư giãn."}],comprehensionQuestions:[{question:"What will the writer do on Saturday morning?",options:["Meet friends","Visit grandmother","Watch a movie","Stay at home"],correct:1},{question:"How will the writer travel to the countryside?",options:["By car","By bus","By bike","On foot"],correct:1},{question:"What will the writer do with friends on Saturday afternoon?",options:["Study together","Play soccer","Go swimming","Cook dinner"],correct:1},{question:"Why does the writer need to prepare on Sunday?",options:["For a trip","For a math test","For a party","For a meeting"],correct:1},{question:"How does the writer feel about weekends?",options:["Bored","Sad","Happy","Tired"],correct:2}],answers:[1,1,1,1,2],answerExplanationVi:"1. Người viết sẽ thăm bà vào sáng thứ Bảy. 2. Người viết sẽ đi bằng xe buýt. 3. Người viết sẽ chơi bóng đá với bạn bè. 4. Người viết cần chuẩn bị cho bài kiểm tra toán. 5. Người viết yêu cuối tuần và cảm thấy vui vẻ.",discussionQuestions:["Bạn thường làm gì vào cuối tuần?","Bạn có thích lập kế hoạch cho cuối tuần không? Tại sao?","Bạn thích ở nhà hay ra ngoài vào cuối tuần?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I have some exciting plans for this weekend.","On Saturday morning, I will visit my grandmother.","I will go there by bus.","She lives in the countryside.","I love weekends because I can relax."]},{id:"a2_6",level:"A2",topic:"health",title:"Getting Enough Exercise",titleVi:"Tập Thể Dục Đầy Đủ",illustrationEmoji:"🏃",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: tập thể dục đầy đủ.",englishText:`My doctor told me that I need to get enough **exercise** every day. Last month, I started a new **routine** to stay healthy. Every morning, I **jog** for 30 minutes in the park near my house. The air is fresh and I feel **energized** after running.

I also **joined** a sports club at school. We play badminton twice a week. It is a fun **sport** and it helps me move my body. My friend taught me how to serve the shuttlecock **correctly**. Now I can play much better than before.

My parents are **proud** because I am more active now. I spend less time watching **television** and more time playing outside. Exercise makes me **stronger** and healthier. I think everyone should exercise **regularly**.`,vietnameseText:`Bác sĩ của tôi nói rằng tôi cần tập **thể dục** đầy đủ mỗi ngày. Tháng trước, tôi đã bắt đầu một **thói quen** mới để giữ sức khỏe. Mỗi sáng, tôi **chạy bộ** 30 phút trong công viên gần nhà. Không khí trong lành và tôi cảm thấy **tràn đầy năng lượng** sau khi chạy.

Tôi cũng đã **tham gia** câu lạc bộ thể thao ở trường. Chúng tôi chơi cầu lông hai lần một tuần. Đó là một môn **thể thao** thú vị và nó giúp tôi vận động cơ thể. Bạn tôi đã dạy tôi cách giao cầu **đúng cách**. Bây giờ tôi có thể chơi tốt hơn nhiều so với trước đây.

Bố mẹ tôi **tự hào** vì tôi năng động hơn. Tôi dành ít thời gian xem **tivi** hơn và nhiều thời gian chơi ngoài trời hơn. Tập thể dục giúp tôi **khỏe hơn** và lành mạnh hơn. Tôi nghĩ mọi người nên tập thể dục **thường xuyên**.`,vocabularyFocus:[{word:"exercise",vi:"tập thể dục",example:""},{word:"routine",vi:"thói quen",example:""},{word:"jog",vi:"chạy bộ",example:""},{word:"energized",vi:"tràn đầy năng lượng",example:""},{word:"joined",vi:"tham gia",example:""},{word:"sport",vi:"thể thao",example:""},{word:"correctly",vi:"đúng cách",example:""},{word:"regularly",vi:"thường xuyên",example:""}],phrases:[{en:"I need to get enough exercise every day.",vi:"Tôi cần tập thể dục đầy đủ mỗi ngày."},{en:"Every morning, I jog for 30 minutes.",vi:"Mỗi sáng, tôi chạy bộ 30 phút."},{en:"I joined a sports club at school.",vi:"Tôi đã tham gia câu lạc bộ thể thao ở trường."},{en:"Exercise makes me stronger and healthier.",vi:"Tập thể dục giúp tôi khỏe hơn và lành mạnh hơn."},{en:"I think everyone should exercise regularly.",vi:"Tôi nghĩ mọi người nên tập thể dục thường xuyên."}],comprehensionQuestions:[{question:"What did the doctor tell the writer to do?",options:["Eat more food","Get enough exercise","Sleep more","Drink more water"],correct:1},{question:"How long does the writer jog every morning?",options:["15 minutes","20 minutes","30 minutes","45 minutes"],correct:2},{question:"What sport does the writer play at the club?",options:["Soccer","Badminton","Basketball","Swimming"],correct:1},{question:"Who taught the writer to serve the shuttlecock?",options:["A teacher","A coach","A friend","Father"],correct:2},{question:"How do the parents feel about the writer?",options:["Worried","Proud","Angry","Sad"],correct:1}],answers:[1,2,1,2,1],answerExplanationVi:"1. Bác sĩ bảo người viết tập thể dục đầy đủ. 2. Người viết chạy bộ 30 phút mỗi sáng. 3. Họ chơi cầu lông ở câu lạc bộ. 4. Một người bạn đã dạy người viết cách giao cầu. 5. Bố mẹ tự hào vì người viết năng động hơn.",discussionQuestions:["Bạn có tập thể dục thường xuyên không? Bạn thích môn thể thao nào?","Theo bạn, tập thể dục có lợi ích gì cho sức khỏe?","Bạn có lời khuyên gì cho người muốn bắt đầu tập thể dục?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I need to get enough exercise every day.","Every morning, I jog for 30 minutes.","I also joined a sports club at school.","Exercise makes me stronger and healthier.","I think everyone should exercise regularly."]},{id:"a2_7",level:"A2",topic:"family",title:"Helping My Grandparents",titleVi:"Giúp Đỡ Ông Bà",illustrationEmoji:"🧑‍🌾",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: giúp đỡ ông bà.",englishText:`Every weekend, I **visit** my grandparents and help them with housework. They live in a small house near the **river**. My grandfather is 70 years old and my grandmother is 68. They are **happy** when I come to see them.

Last Saturday, I helped my grandfather in the **garden**. We planted some vegetables like tomatoes and **cabbage**. I also **watered** the flowers. My grandmother made lunch for us. She cooked my **favorite** dish – fried fish with rice.

In the afternoon, I helped **clean** the house. I swept the floor and **washed** the dishes. My grandparents said I am a **good** helper. I love spending time with them because they tell me interesting **stories** about their youth.`,vietnameseText:`Mỗi cuối tuần, tôi **thăm** ông bà và giúp họ làm việc nhà. Ông bà sống trong một ngôi nhà nhỏ gần **dòng sông**. Ông tôi 70 tuổi và bà tôi 68 tuổi. Họ **vui** khi tôi đến thăm.

Thứ Bảy tuần trước, tôi đã giúp ông trong **khu vườn**. Chúng tôi trồng một số loại rau như cà chua và **bắp cải**. Tôi cũng đã **tưới** hoa. Bà tôi đã nấu bữa trưa cho chúng tôi. Bà nấu món **yêu thích** của tôi – cá chiên với cơm.

Buổi chiều, tôi giúp **dọn dẹp** nhà cửa. Tôi quét nhà và **rửa** bát đĩa. Ông bà nói tôi là một người giúp việc **tốt**. Tôi yêu thời gian ở bên ông bà vì họ kể cho tôi nghe những **câu chuyện** thú vị về thời trẻ của họ.`,vocabularyFocus:[{word:"visit",vi:"thăm",example:""},{word:"river",vi:"dòng sông",example:""},{word:"happy",vi:"vui",example:""},{word:"garden",vi:"khu vườn",example:""},{word:"watered",vi:"tưới",example:""},{word:"favorite",vi:"yêu thích",example:""},{word:"clean",vi:"dọn dẹp",example:""},{word:"stories",vi:"câu chuyện",example:""}],phrases:[{en:"Every weekend, I visit my grandparents.",vi:"Mỗi cuối tuần, tôi thăm ông bà."},{en:"They are happy when I come to see them.",vi:"Họ vui khi tôi đến thăm."},{en:"We planted some vegetables like tomatoes and cabbage.",vi:"Chúng tôi trồng một số loại rau như cà chua và bắp cải."},{en:"I love spending time with them.",vi:"Tôi yêu thời gian ở bên ông bà."},{en:"They tell me interesting stories about their youth.",vi:"Họ kể cho tôi nghe những câu chuyện thú vị về thời trẻ của họ."}],comprehensionQuestions:[{question:"How old is the writer grandfather?",options:["65","68","70","72"],correct:2},{question:"What did the writer help grandfather do in the garden?",options:["Water flowers","Plant vegetables","Pick fruits","Cut grass"],correct:1},{question:"What was the writer favorite dish that grandmother cooked?",options:["Fried fish","Spring rolls","Beef stew","Chicken soup"],correct:0},{question:"What did the writer do in the afternoon?",options:["Watched TV","Played games","Cleaned the house","Read books"],correct:2},{question:"Why does the writer love spending time with grandparents?",options:["They give gifts","They tell stories","They cook food","They play games"],correct:1}],answers:[2,1,0,2,1],answerExplanationVi:"1. Ông nội 70 tuổi. 2. Người viết giúp ông trồng rau trong vườn. 3. Món yêu thích là cá chiên. 4. Buổi chiều người viết dọn dẹp nhà cửa. 5. Người viết yêu thời gian bên ông bà vì họ kể chuyện thú vị.",discussionQuestions:["Bạn thường làm gì khi thăm ông bà?","Tại sao việc dành thời gian cho gia đình lại quan trọng?","Bạn học được điều gì từ ông bà của mình?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["Every weekend, I visit my grandparents.","They are happy when I come to see them.","I helped my grandfather in the garden.","My grandmother made lunch for us.","I love spending time with them."]},{id:"a2_8",level:"A2",topic:"environment",title:"Saving Water at Home",titleVi:"Tiết Kiệm Nước Ở Nhà",illustrationEmoji:"💧",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: tiết kiệm nước ở nhà.",englishText:`Water is very **important** for our life. My teacher taught us how to save **water** at home. Now my family tries to use less water every day. We have learned many **simple** ways to protect this resource.

First, I always turn **off** the tap when I brush my teeth. I also take **shorter** showers. My mother uses the washing machine only when it is **full**. My father fixed a **leaking** pipe in the bathroom. These small actions help us save a lot of water.

We also **collect** rainwater to water the plants in the garden. My little brother knows not to **waste** water when he plays. Saving water is good for the **environment** and also reduces our water bill. I think everyone should save water **every day**.`,vietnameseText:`Nước rất **quan trọng** đối với cuộc sống của chúng ta. Giáo viên của tôi đã dạy chúng tôi cách tiết kiệm **nước** ở nhà. Bây giờ gia đình tôi cố gắng sử dụng ít nước hơn mỗi ngày. Chúng tôi đã học được nhiều cách **đơn giản** để bảo vệ tài nguyên này.

Đầu tiên, tôi luôn **tắt** vòi nước khi đánh răng. Tôi cũng đi tắm **nhanh hơn**. Mẹ tôi chỉ sử dụng máy giặt khi nó **đầy**. Bố tôi đã sửa một đường ống **bị rò rỉ** trong phòng tắm. Những hành động nhỏ này giúp chúng tôi tiết kiệm rất nhiều nước.

Chúng tôi cũng **thu gom** nước mưa để tưới cây trong vườn. Em trai tôi biết không được **lãng phí** nước khi chơi. Tiết kiệm nước tốt cho **môi trường** và cũng giảm hóa đơn tiền nước của chúng tôi. Tôi nghĩ mọi người nên tiết kiệm nước **mỗi ngày**.`,vocabularyFocus:[{word:"important",vi:"quan trọng",example:""},{word:"water",vi:"nước",example:""},{word:"simple",vi:"đơn giản",example:""},{word:"turn off",vi:"tắt",example:""},{word:"shorter",vi:"nhanh hơn",example:""},{word:"full",vi:"đầy",example:""},{word:"leaking",vi:"bị rò rỉ",example:""},{word:"waste",vi:"lãng phí",example:""}],phrases:[{en:"Water is very important for our life.",vi:"Nước rất quan trọng đối với cuộc sống của chúng ta."},{en:"I always turn off the tap when I brush my teeth.",vi:"Tôi luôn tắt vòi nước khi đánh răng."},{en:"My father fixed a leaking pipe in the bathroom.",vi:"Bố tôi đã sửa một đường ống bị rò rỉ trong phòng tắm."},{en:"We collect rainwater to water the plants.",vi:"Chúng tôi thu gom nước mưa để tưới cây."},{en:"Saving water is good for the environment.",vi:"Tiết kiệm nước tốt cho môi trường."}],comprehensionQuestions:[{question:"Who taught the writer how to save water?",options:["Mother","Father","Teacher","Friend"],correct:2},{question:"What does the writer do when brushing teeth?",options:["Uses a cup","Turns off the tap","Takes a shower","Sings a song"],correct:1},{question:"What did the father fix in the bathroom?",options:["The light","The door","A leaking pipe","The mirror"],correct:2},{question:"What do they collect to water the plants?",options:["Bottled water","Rainwater","River water","Tap water"],correct:1},{question:"Why is saving water good?",options:["It saves money","It is fun","It is easy","It is fast"],correct:0}],answers:[2,1,2,1,0],answerExplanationVi:"1. Giáo viên đã dạy người viết tiết kiệm nước. 2. Người viết tắt vòi nước khi đánh răng. 3. Bố đã sửa đường ống bị rò rỉ. 4. Họ thu gom nước mưa để tưới cây. 5. Tiết kiệm nước giúp giảm hóa đơn tiền nước.",discussionQuestions:["Gia đình bạn có tiết kiệm nước không? Bằng cách nào?","Theo bạn, tại sao bảo vệ môi trường lại quan trọng?","Bạn có thể làm gì để tiết kiệm nước mỗi ngày?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["Water is very important for our life.","My teacher taught us how to save water.","I always turn off the tap when I brush my teeth.","We collect rainwater to water the plants.","Saving water is good for the environment."]},{id:"a2_9",level:"A2",topic:"school",title:"My Favorite Teacher",titleVi:"Cô Giáo Yêu Thích Của Tôi",illustrationEmoji:"👩‍🏫",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: cô giáo yêu thích của tôi.",englishText:`My **favorite** teacher is Mrs. Lan, my English teacher. She is young and **kind**. She always comes to class with a big **smile**. She makes learning English very **interesting** and fun. I never feel bored in her lessons.

Mrs. Lan uses many **creative** activities in class. We play language games, sing English songs, and **practice** conversations. She also shows us **videos** about different cultures. Last week, we learned about Halloween. She brought **pumpkins** and we carved them together.

She always **encourages** us to speak English **confidently**. She says making **mistakes** is a part of learning. Thanks to Mrs. Lan, my English has **improved** a lot. I want to become a teacher like her in the future.`,vietnameseText:`Cô giáo **yêu thích** của tôi là cô Lan, giáo viên tiếng Anh của tôi. Cô ấy trẻ và **tốt bụng**. Cô ấy luôn đến lớp với một nụ cười **tươi**. Cô ấy làm cho việc học tiếng Anh trở nên rất **thú vị** và vui vẻ. Tôi không bao giờ cảm thấy chán trong các bài học của cô.

Cô Lan sử dụng nhiều hoạt động **sáng tạo** trong lớp. Chúng tôi chơi trò chơi ngôn ngữ, hát bài hát tiếng Anh và **luyện tập** hội thoại. Cô ấy cũng cho chúng tôi xem **video** về các nền văn hóa khác nhau. Tuần trước, chúng tôi đã học về Halloween. Cô ấy mang **bí ngô** đến và chúng tôi cùng nhau khắc.

Cô ấy luôn **khuyến khích** chúng tôi nói tiếng Anh một cách **tự tin**. Cô ấy nói **mắc lỗi** là một phần của việc học. Nhờ cô Lan, tiếng Anh của tôi đã **cải thiện** rất nhiều. Tôi muốn trở thành giáo viên như cô ấy trong tương lai.`,vocabularyFocus:[{word:"favorite",vi:"yêu thích",example:""},{word:"kind",vi:"tốt bụng",example:""},{word:"smile",vi:"nụ cười",example:""},{word:"interesting",vi:"thú vị",example:""},{word:"creative",vi:"sáng tạo",example:""},{word:"practice",vi:"luyện tập",example:""},{word:"encourages",vi:"khuyến khích",example:""},{word:"improved",vi:"cải thiện",example:""}],phrases:[{en:"My favorite teacher is Mrs. Lan, my English teacher.",vi:"Cô giáo yêu thích của tôi là cô Lan, giáo viên tiếng Anh của tôi."},{en:"She always comes to class with a big smile.",vi:"Cô ấy luôn đến lớp với một nụ cười tươi."},{en:"She uses many creative activities in class.",vi:"Cô ấy sử dụng nhiều hoạt động sáng tạo trong lớp."},{en:"She always encourages us to speak English.",vi:"Cô ấy luôn khuyến khích chúng tôi nói tiếng Anh."},{en:"Thanks to Mrs. Lan, my English has improved a lot.",vi:"Nhờ cô Lan, tiếng Anh của tôi đã cải thiện rất nhiều."}],comprehensionQuestions:[{question:"What subject does Mrs. Lan teach?",options:["Math","English","History","Science"],correct:1},{question:"How does Mrs. Lan come to class?",options:["With a book","With a big smile","With a bag","With a friend"],correct:1},{question:"What did the class learn about last week?",options:["Christmas","Halloween","Tet","Thanksgiving"],correct:1},{question:"What did Mrs. Lan bring to class for Halloween?",options:["Candies","Pumpkins","Costumes","Masks"],correct:1},{question:"What does Mrs. Lan say about making mistakes?",options:["It is bad","It is part of learning","It is funny","It is wrong"],correct:1}],answers:[1,1,1,1,1],answerExplanationVi:"1. Cô Lan dạy tiếng Anh. 2. Cô Lan đến lớp với nụ cười tươi. 3. Tuần trước họ học về Halloween. 4. Cô Lan mang bí ngô đến lớp. 5. Cô nói mắc lỗi là một phần của việc học.",discussionQuestions:["Bạn có giáo viên yêu thích không? Vì sao bạn thích người đó?","Giáo viên tốt cần có những phẩm chất gì?","Bạn muốn trở thành giáo viên không? Tại sao?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My favorite teacher is Mrs. Lan, my English teacher.","She always comes to class with a big smile.","She uses many creative activities in class.","She always encourages us to speak English confidently.","Thanks to Mrs. Lan, my English has improved a lot."]},{id:"a2_10",level:"A2",topic:"travel",title:"A Journey to Hue",titleVi:"Hành Trình Đến Huế",illustrationEmoji:"🏯",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: hành trình đến huế.",englishText:`Last summer, my family took a **trip** to Hue. We traveled by **train** from Hanoi. The journey took about 14 hours. I enjoyed watching the **scenery** through the window. There were green fields and **mountains** along the way.

When we arrived, we visited the **Imperial City**. It is a huge **complex** with many temples and palaces. I learned about the Nguyen **dynasty** and the history of Vietnam. We also took a boat **ride** on the Perfume River. The sunset was **beautiful**.

We tried Hue **cuisine** which is famous for its flavor. I ate bun bo Hue – a spicy **beef** noodle soup. It was **delicious**! The people in Hue are **gentle** and friendly. I took many photos and bought **gifts** for my friends. It was an unforgettable trip.`,vietnameseText:`Mùa hè năm ngoái, gia đình tôi đã có một **chuyến đi** đến Huế. Chúng tôi di chuyển bằng tàu **hỏa** từ Hà Nội. Hành trình mất khoảng 14 giờ. Tôi thích ngắm **phong cảnh** qua cửa sổ. Có những cánh đồng xanh và **núi non** dọc đường.

Khi đến nơi, chúng tôi đã thăm **Đại Nội**. Đó là một **quần thể** rộng lớn với nhiều đền đài và cung điện. Tôi đã học về **triều** Nguyễn và lịch sử Việt Nam. Chúng tôi cũng đi **thuyền** trên sông Hương. Hoàng hôn thật **đẹp**.

Chúng tôi đã thử ẩm **thực** Huế nổi tiếng với hương vị đặc trưng. Tôi đã ăn bún bò Huế – một món mì bò **bò** cay. Nó thật **ngon**! Người dân Huế **dịu dàng** và thân thiện. Tôi đã chụp nhiều ảnh và mua **quà** cho bạn bè. Đó là một chuyến đi khó quên.`,vocabularyFocus:[{word:"trip",vi:"chuyến đi",example:""},{word:"train",vi:"tàu hỏa",example:""},{word:"scenery",vi:"phong cảnh",example:""},{word:"mountains",vi:"núi non",example:""},{word:"complex",vi:"quần thể",example:""},{word:"ride",vi:"chuyến đi thuyền",example:""},{word:"cuisine",vi:"ẩm thực",example:""},{word:"delicious",vi:"ngon",example:""}],phrases:[{en:"My family took a trip to Hue.",vi:"Gia đình tôi đã có một chuyến đi đến Huế."},{en:"We traveled by train from Hanoi.",vi:"Chúng tôi di chuyển bằng tàu hỏa từ Hà Nội."},{en:"We visited the Imperial City.",vi:"Chúng tôi đã thăm Đại Nội."},{en:"We tried Hue cuisine which is famous for its flavor.",vi:"Chúng tôi đã thử ẩm thực Huế nổi tiếng với hương vị đặc trưng."},{en:"It was an unforgettable trip.",vi:"Đó là một chuyến đi khó quên."}],comprehensionQuestions:[{question:"How did the writer family travel to Hue?",options:["By car","By train","By plane","By bus"],correct:1},{question:"How long did the journey take?",options:["10 hours","12 hours","14 hours","16 hours"],correct:2},{question:"What did the writer visit in Hue?",options:["The beach","The Imperial City","The market","The mountain"],correct:1},{question:"What dish did the writer try in Hue?",options:["Pho","Bun bo Hue","Com tam","Banh mi"],correct:1},{question:"How would the writer describe Hue people?",options:["Loud","Gentle","Strict","Shy"],correct:1}],answers:[1,2,1,1,1],answerExplanationVi:"1. Gia đình đi Huế bằng tàu hỏa. 2. Hành trình mất 14 giờ. 3. Họ đã thăm Đại Nội. 4. Người viết đã thử bún bò Huế. 5. Người dân Huế dịu dàng và thân thiện.",discussionQuestions:["Bạn đã từng đi Huế chưa? Bạn có ấn tượng gì?","Bạn thích đi du lịch bằng phương tiện nào nhất?","Theo bạn, tại sao nên tìm hiểu lịch sử khi đi du lịch?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["We traveled by train from Hanoi.","The journey took about 14 hours.","We visited the Imperial City.","We tried Hue cuisine which is famous.","It was an unforgettable trip."]},{id:"a2_11",level:"A2",topic:"food",title:"Making Spring Rolls",titleVi:"Làm Nem Rán",illustrationEmoji:"🥟",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: làm nem rán.",englishText:`Last weekend, my mother taught me how to make spring **rolls**. It is a traditional Vietnamese **dish** that everyone loves. We **prepared** all the ingredients in the kitchen.

First, we **chopped** the pork and vegetables into small pieces. We used carrots, mushrooms, and **bean** sprouts. Then we mixed them with **seasoning** and eggs. My mother showed me how to **wrap** the filling in rice paper. It was **tricky** at first, but I learned quickly.

After wrapping, we **fried** the rolls until they were golden and crispy. The kitchen smelled **wonderful**. We served them with fish **sauce** and fresh lettuce. My father said they were as **good** as the ones from a restaurant. I felt so **proud** of myself!`,vietnameseText:`Cuối tuần trước, mẹ tôi đã dạy tôi cách làm nem **rán**. Đó là một **món** ăn truyền thống của Việt Nam mà mọi người đều yêu thích. Chúng tôi **chuẩn bị** tất cả nguyên liệu trong bếp.

Đầu tiên, chúng tôi **băm** nhỏ thịt heo và rau củ. Chúng tôi sử dụng cà rốt, nấm và **giá** đỗ. Sau đó chúng tôi trộn chúng với **gia vị** và trứng. Mẹ tôi chỉ cho tôi cách **cuốn** nhân trong bánh tráng. Lúc đầu **hơi khó**, nhưng tôi đã học nhanh.

Sau khi cuốn, chúng tôi **chiên** nem cho đến khi vàng và giòn. Căn bếp có mùi thơm **tuyệt vời**. Chúng tôi ăn kèm với **nước** mắm và xà lách tươi. Bố tôi nói chúng **ngon** như nem ở nhà hàng. Tôi cảm thấy rất **tự hào** về bản thân!`,vocabularyFocus:[{word:"rolls",vi:"nem rán",example:""},{word:"dish",vi:"món ăn",example:""},{word:"prepared",vi:"chuẩn bị",example:""},{word:"chopped",vi:"băm nhỏ",example:""},{word:"wrapped",vi:"cuốn",example:""},{word:"fried",vi:"chiên",example:""},{word:"sauce",vi:"nước mắm",example:""},{word:"proud",vi:"tự hào",example:""}],phrases:[{en:"My mother taught me how to make spring rolls.",vi:"Mẹ tôi đã dạy tôi cách làm nem rán."},{en:"We prepared all the ingredients in the kitchen.",vi:"Chúng tôi chuẩn bị tất cả nguyên liệu trong bếp."},{en:"My mother showed me how to wrap the filling.",vi:"Mẹ tôi chỉ cho tôi cách cuốn nhân."},{en:"We fried the rolls until they were golden and crispy.",vi:"Chúng tôi chiên nem cho đến khi vàng và giòn."},{en:"I felt so proud of myself!",vi:"Tôi cảm thấy rất tự hào về bản thân!"}],comprehensionQuestions:[{question:"Who taught the writer to make spring rolls?",options:["Father","Grandmother","Mother","Friend"],correct:2},{question:"What did they use to wrap the filling?",options:["Lettuce","Rice paper","Bread","Tortilla"],correct:1},{question:"How did they cook the spring rolls?",options:["Boiled","Steamed","Fried","Baked"],correct:2},{question:"What did they serve with the spring rolls?",options:["Ketchup","Fish sauce","Soy sauce","Chili sauce"],correct:1},{question:"How did the writer feel after making spring rolls?",options:["Tired","Proud","Hungry","Worried"],correct:1}],answers:[2,1,2,1,1],answerExplanationVi:"1. Mẹ đã dạy người viết làm nem rán. 2. Họ dùng bánh tráng để cuốn nhân. 3. Họ chiên nem. 4. Họ ăn kèm với nước mắm. 5. Người viết cảm thấy tự hào.",discussionQuestions:["Bạn có biết làm nem rán không? Bạn thích món ăn truyền thống nào?","Theo bạn, tại sao nên học nấu các món ăn truyền thống?","Bạn thường ăn nem rán với loại nước chấm gì?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My mother taught me how to make spring rolls.","We prepared all the ingredients in the kitchen.","We fried the rolls until they were golden.","We served them with fish sauce.","I felt so proud of myself!"]},{id:"a2_12",level:"A2",topic:"work",title:"My First Job Experience",titleVi:"Trải Nghiệm Công Việc Đầu Tiên",illustrationEmoji:"👔",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: trải nghiệm công việc đầu tiên.",englishText:`Last summer, I had my first **job** at a small café near my house. I worked there for two **months**. It was a great **experience** for me. I learned many new **skills**.

My main **duty** was to serve customers and clean the tables. I also helped the **chef** prepare simple dishes like sandwiches and salads. At first, I was **nervous** because I did not want to make mistakes. But my **colleagues** were very helpful. They showed me how to do everything correctly.

I earned my first **salary** and felt very proud. I bought a **gift** for my mother with the money. This job taught me the **value** of hard work. Now I understand why my parents work so **hard** every day. I want to save money for my future **education**.`,vietnameseText:`Mùa hè năm ngoái, tôi đã có **công việc** đầu tiên tại một quán cà phê nhỏ gần nhà. Tôi đã làm việc ở đó trong hai **tháng**. Đó là một **trải nghiệm** tuyệt vời đối với tôi. Tôi đã học được nhiều **kỹ năng** mới.

**Nhiệm vụ** chính của tôi là phục vụ khách hàng và lau bàn. Tôi cũng giúp **đầu bếp** chuẩn bị các món ăn đơn giản như bánh sandwich và salad. Lúc đầu, tôi rất **lo lắng** vì không muốn mắc sai lầm. Nhưng **đồng nghiệp** của tôi rất hữu ích. Họ chỉ cho tôi cách làm mọi thứ đúng cách.

Tôi đã nhận được **lương** đầu tiên và cảm thấy rất tự hào. Tôi đã mua một **món quà** cho mẹ bằng số tiền đó. Công việc này đã dạy tôi **giá trị** của lao động. Bây giờ tôi hiểu tại sao bố mẹ tôi làm việc **vất vả** mỗi ngày. Tôi muốn tiết kiệm tiền cho **học vấn** tương lai của mình.`,vocabularyFocus:[{word:"job",vi:"công việc",example:""},{word:"months",vi:"tháng",example:""},{word:"experience",vi:"trải nghiệm",example:""},{word:"skills",vi:"kỹ năng",example:""},{word:"duty",vi:"nhiệm vụ",example:""},{word:"nervous",vi:"lo lắng",example:""},{word:"colleagues",vi:"đồng nghiệp",example:""},{word:"salary",vi:"lương",example:""}],phrases:[{en:"I had my first job at a small café.",vi:"Tôi đã có công việc đầu tiên tại một quán cà phê nhỏ."},{en:"It was a great experience for me.",vi:"Đó là một trải nghiệm tuyệt vời đối với tôi."},{en:"My main duty was to serve customers.",vi:"Nhiệm vụ chính của tôi là phục vụ khách hàng."},{en:"I earned my first salary and felt very proud.",vi:"Tôi đã nhận được lương đầu tiên và cảm thấy rất tự hào."},{en:"This job taught me the value of hard work.",vi:"Công việc này đã dạy tôi giá trị của lao động."}],comprehensionQuestions:[{question:"Where did the writer work last summer?",options:["A restaurant","A café","A shop","A library"],correct:1},{question:"How long did the writer work there?",options:["One month","Two months","Three months","Four months"],correct:1},{question:"What was the writer main duty?",options:["Cooking food","Serving customers","Cleaning dishes","Managing money"],correct:1},{question:"What did the writer buy with the first salary?",options:["A book","A phone","A gift for mother","Clothes"],correct:2},{question:"What did the job teach the writer?",options:["How to cook","Value of hard work","How to drive","How to dance"],correct:1}],answers:[1,1,1,2,1],answerExplanationVi:"1. Người viết làm việc tại một quán cà phê. 2. Người viết làm việc ở đó hai tháng. 3. Nhiệm vụ chính là phục vụ khách hàng. 4. Người viết mua quà cho mẹ bằng lương đầu tiên. 5. Công việc dạy người viết giá trị của lao động.",discussionQuestions:["Bạn đã có công việc đầu tiên chưa? Cảm giác thế nào?","Theo bạn, làm việc khi còn đi học có lợi ích gì?","Bạn muốn làm công việc gì trong tương lai?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I had my first job at a small café.","It was a great experience for me.","My main duty was to serve customers.","I earned my first salary.","This job taught me the value of hard work."]},{id:"a2_13",level:"A2",topic:"health",title:"A Visit to the Doctor",titleVi:"Đi Khám Bác Sĩ",illustrationEmoji:"👨‍⚕️",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: đi khám bác sĩ.",englishText:`Last week, I had a **visit** to the doctor because I had a bad **cough** and a **fever**. My mother took me to the clinic near our house. The waiting room was **crowded** with many patients.

When it was my **turn**, the doctor checked my temperature. It was 39 degrees. He **listened** to my breathing with a stethoscope. Then he looked at my **throat** and said it was red. He told me I had a **cold** and needed to rest.

The doctor **prescribed** some medicine and told me to drink a lot of water. He said I should **avoid** cold drinks and spicy food. I stayed at home for two days. I **followed** his advice and felt better quickly. Now I always wear a **jacket** when the weather is cold.`,vietnameseText:`Tuần trước, tôi đã đi **khám** bác sĩ vì tôi bị **ho** nặng và **sốt**. Mẹ tôi đưa tôi đến phòng khám gần nhà. Phòng chờ **đông đúc** với nhiều bệnh nhân.

Khi đến **lượt** tôi, bác sĩ đã kiểm tra nhiệt độ của tôi. Nó là 39 độ. Ông ấy **lắng nghe** nhịp thở của tôi bằng ống nghe. Sau đó ông ấy nhìn vào **họng** của tôi và nói nó bị đỏ. Ông ấy nói tôi bị **cảm lạnh** và cần nghỉ ngơi.

Bác sĩ đã **kê đơn** một số thuốc và bảo tôi uống nhiều nước. Ông ấy nói tôi nên **tránh** đồ uống lạnh và đồ ăn cay. Tôi đã ở nhà trong hai ngày. Tôi đã **làm theo** lời khuyên của ông ấy và cảm thấy khỏe hơn nhanh chóng. Bây giờ tôi luôn mặc **áo khoác** khi thời tiết lạnh.`,vocabularyFocus:[{word:"visit",vi:"đi khám",example:""},{word:"cough",vi:"ho",example:""},{word:"fever",vi:"sốt",example:""},{word:"crowded",vi:"đông đúc",example:""},{word:"listened",vi:"lắng nghe",example:""},{word:"throat",vi:"họng",example:""},{word:"prescribed",vi:"kê đơn",example:""},{word:"avoid",vi:"tránh",example:""}],phrases:[{en:"I had a visit to the doctor because I had a bad cough.",vi:"Tôi đã đi khám bác sĩ vì tôi bị ho nặng."},{en:"The doctor checked my temperature.",vi:"Bác sĩ đã kiểm tra nhiệt độ của tôi."},{en:"He listened to my breathing with a stethoscope.",vi:"Ông ấy lắng nghe nhịp thở của tôi bằng ống nghe."},{en:"The doctor prescribed some medicine.",vi:"Bác sĩ đã kê đơn một số thuốc."},{en:"I followed his advice and felt better quickly.",vi:"Tôi đã làm theo lời khuyên của ông ấy và cảm thấy khỏe hơn nhanh chóng."}],comprehensionQuestions:[{question:"Why did the writer visit the doctor?",options:["Headache","Cough and fever","Stomachache","Toothache"],correct:1},{question:"What was the writer temperature?",options:["37 degrees","38 degrees","39 degrees","40 degrees"],correct:2},{question:"What did the doctor use to check breathing?",options:["A thermometer","A stethoscope","A scale","A mirror"],correct:1},{question:"What did the doctor say the writer should avoid?",options:["Hot food","Cold drinks and spicy food","Fruit","Vegetables"],correct:1},{question:"How many days did the writer stay at home?",options:["One day","Two days","Three days","Four days"],correct:1}],answers:[1,2,1,1,1],answerExplanationVi:"1. Người viết đi khám vì ho và sốt. 2. Nhiệt độ là 39 độ. 3. Bác sĩ dùng ống nghe để kiểm tra nhịp thở. 4. Người viết nên tránh đồ uống lạnh và đồ cay. 5. Người viết ở nhà hai ngày.",discussionQuestions:["Bạn có sợ đi khám bác sĩ không? Tại sao?","Bạn thường làm gì khi bị cảm lạnh?","Theo bạn, tại sao cần uống nhiều nước khi bị sốt?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I had a visit to the doctor.","The doctor checked my temperature.","He listened to my breathing with a stethoscope.","He told me I had a cold.","I followed his advice and felt better."]},{id:"a2_14",level:"A2",topic:"daily life",title:"Learning to Cook",titleVi:"Học Nấu Ăn",illustrationEmoji:"🍳",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: học nấu ăn.",englishText:`I started **learning** to cook three months ago. I wanted to help my mother in the **kitchen**. She was happy to teach me. Now I can **cook** some simple dishes by myself.

The first dish I learned was fried **rice**. It is easy to make. I **chopped** some garlic and vegetables. Then I **stir-fried** them with rice and eggs. My family said it **tasted** good. That made me very happy.

Next, I learned to make **omelette** for breakfast. I beat the **eggs** and added a little salt. I poured them into a hot pan with **oil**. It was golden and delicious. Cooking is a useful **skill**. I am happy that I can now prepare meals for my **family** when my mother is busy.`,vietnameseText:`Tôi đã bắt đầu **học** nấu ăn từ ba tháng trước. Tôi muốn giúp mẹ trong **bếp**. Mẹ rất vui khi dạy tôi. Bây giờ tôi có thể tự **nấu** một số món ăn đơn giản.

Món đầu tiên tôi học là cơm **rang**. Nó dễ làm. Tôi đã **băm** một ít tỏi và rau củ. Sau đó tôi **xào** chúng với cơm và trứng. Gia đình tôi nói nó **có vị** ngon. Điều đó làm tôi rất vui.

Tiếp theo, tôi học làm **trứng tráng** cho bữa sáng. Tôi đánh **trứng** và thêm một chút muối. Tôi đổ chúng vào chảo nóng với **dầu**. Nó vàng và thơm ngon. Nấu ăn là một **kỹ năng** hữu ích. Tôi rất vui vì bây giờ tôi có thể chuẩn bị bữa ăn cho **gia đình** khi mẹ bận.`,vocabularyFocus:[{word:"learning",vi:"học",example:""},{word:"kitchen",vi:"bếp",example:""},{word:"cook",vi:"nấu",example:""},{word:"chopped",vi:"băm",example:""},{word:"stir-fried",vi:"xào",example:""},{word:"tasted",vi:"có vị",example:""},{word:"omelette",vi:"trứng tráng",example:""},{word:"skill",vi:"kỹ năng",example:""}],phrases:[{en:"I started learning to cook three months ago.",vi:"Tôi đã bắt đầu học nấu ăn từ ba tháng trước."},{en:"The first dish I learned was fried rice.",vi:"Món đầu tiên tôi học là cơm rang."},{en:"I stir-fried them with rice and eggs.",vi:"Tôi xào chúng với cơm và trứng."},{en:"Cooking is a useful skill.",vi:"Nấu ăn là một kỹ năng hữu ích."},{en:"I can now prepare meals for my family.",vi:"Bây giờ tôi có thể chuẩn bị bữa ăn cho gia đình."}],comprehensionQuestions:[{question:"When did the writer start learning to cook?",options:["One month ago","Two months ago","Three months ago","Six months ago"],correct:2},{question:"What was the first dish the writer learned?",options:["Omelette","Fried rice","Noodle soup","Spring rolls"],correct:1},{question:"What did the writer add to the rice?",options:["Meat and vegetables","Garlic and eggs","Fish and sauce","Shrimp and pork"],correct:1},{question:"What did the writer make for breakfast?",options:["Sandwich","Omelette","Porridge","Fruit salad"],correct:1},{question:"Why did the writer want to learn cooking?",options:["To be a chef","To help mother","To win a contest","To save money"],correct:1}],answers:[2,1,1,1,1],answerExplanationVi:"1. Người viết bắt đầu học nấu ăn từ ba tháng trước. 2. Món đầu tiên là cơm rang. 3. Người viết xào tỏi và trứng với cơm. 4. Người viết làm trứng tráng cho bữa sáng. 5. Người viết muốn giúp mẹ trong bếp.",discussionQuestions:["Bạn có biết nấu ăn không? Bạn đã học nấu món gì đầu tiên?","Theo bạn, nấu ăn có khó không? Tại sao?","Bạn muốn học nấu món gì tiếp theo?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I started learning to cook three months ago.","The first dish I learned was fried rice.","I stir-fried them with rice and eggs.","Cooking is a useful skill.","I can now prepare meals for my family."]},{id:"a2_15",level:"A2",topic:"technology",title:"Using a Smartphone Safely",titleVi:"Sử Dụng Điện Thoại An Toàn",illustrationEmoji:"📱",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: sử dụng điện thoại an toàn.",englishText:`I got my first **smartphone** last year for my birthday. It is very **useful** for studying and communicating with friends. But my father **taught** me how to use it safely.

First, I should not **share** my personal information online. I never tell strangers my **address** or phone number. I also **set** a strong password to protect my phone. My father said I should **download** apps only from official stores.

I should not use my phone for too **long** because it is bad for my eyes. I take a **break** every 20 minutes when I look at the screen. I also **turn off** my phone during class and at bedtime. Using a smartphone **responsibly** is very important in modern life.`,vietnameseText:`Tôi có **điện thoại thông minh** đầu tiên vào năm ngoái nhân dịp sinh nhật. Nó rất **hữu ích** cho việc học tập và liên lạc với bạn bè. Nhưng bố tôi đã **dạy** tôi cách sử dụng nó một cách an toàn.

Đầu tiên, tôi không nên **chia sẻ** thông tin cá nhân trực tuyến. Tôi không bao giờ nói với người lạ **địa chỉ** hoặc số điện thoại của mình. Tôi cũng **đặt** mật khẩu mạnh để bảo vệ điện thoại. Bố tôi nói tôi nên **tải xuống** ứng dụng chỉ từ các cửa hàng chính thức.

Tôi không nên sử dụng điện thoại quá **lâu** vì nó có hại cho mắt. Tôi **nghỉ giải lao** sau mỗi 20 phút khi nhìn vào màn hình. Tôi cũng **tắt** điện thoại trong giờ học và giờ đi ngủ. Sử dụng điện thoại thông minh một cách **có trách nhiệm** rất quan trọng trong cuộc sống hiện đại.`,vocabularyFocus:[{word:"smartphone",vi:"điện thoại thông minh",example:""},{word:"useful",vi:"hữu ích",example:""},{word:"taught",vi:"dạy",example:""},{word:"share",vi:"chia sẻ",example:""},{word:"address",vi:"địa chỉ",example:""},{word:"set",vi:"đặt",example:""},{word:"download",vi:"tải xuống",example:""},{word:"responsibly",vi:"có trách nhiệm",example:""}],phrases:[{en:"I got my first smartphone last year.",vi:"Tôi có điện thoại thông minh đầu tiên vào năm ngoái."},{en:"My father taught me how to use it safely.",vi:"Bố tôi đã dạy tôi cách sử dụng nó một cách an toàn."},{en:"I should not share my personal information online.",vi:"Tôi không nên chia sẻ thông tin cá nhân trực tuyến."},{en:"I set a strong password to protect my phone.",vi:"Tôi đặt mật khẩu mạnh để bảo vệ điện thoại."},{en:"Using a smartphone responsibly is very important.",vi:"Sử dụng điện thoại thông minh có trách nhiệm rất quan trọng."}],comprehensionQuestions:[{question:"When did the writer get the first smartphone?",options:["This year","Last year","Two years ago","Three years ago"],correct:1},{question:"Who taught the writer to use the smartphone safely?",options:["Mother","Father","Teacher","Brother"],correct:1},{question:"What should the writer not share online?",options:["Photos","Personal information","Music","Games"],correct:1},{question:"How often should the writer take a break from the screen?",options:["Every 10 minutes","Every 20 minutes","Every 30 minutes","Every hour"],correct:1},{question:"When does the writer turn off the phone?",options:["At lunch","During class and bedtime","At dinner","On weekends"],correct:1}],answers:[1,1,1,1,1],answerExplanationVi:"1. Người viết có điện thoại thông minh vào năm ngoái. 2. Bố đã dạy người viết cách sử dụng an toàn. 3. Không nên chia sẻ thông tin cá nhân trực tuyến. 4. Nghỉ giải lao sau mỗi 20 phút. 5. Tắt điện thoại trong giờ học và giờ đi ngủ.",discussionQuestions:["Bạn có điện thoại thông minh không? Bạn dùng nó để làm gì?","Làm thế nào để sử dụng điện thoại an toàn?","Theo bạn, trẻ em nên dùng điện thoại bao nhiêu giờ mỗi ngày?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["I got my first smartphone last year.","My father taught me how to use it safely.","I should not share my personal information online.","I set a strong password to protect my phone.","Using a smartphone responsibly is very important."]},{id:"a2_16",level:"A2",topic:"environment",title:"Planting a Tree",titleVi:"Trồng Một Cái Cây",illustrationEmoji:"🌱",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: trồng một cái cây.",englishText:`Last month, our school had a **planting** event. Each class had to plant a **tree** in the school garden. My class chose a mango **seedling**. We were very **excited** to start.

First, we **dug** a hole in the ground. Then we put the seedling in and covered the **roots** with soil. We **watered** it every day. Our teacher said we need to take **care** of the tree for the whole year.

Now the tree is growing **taller** every week. It has new green **leaves**. I feel **proud** when I look at it. Trees give us **oxygen** and make the air clean. Planting trees is good for the **environment**. I want to plant more trees in my neighborhood next year.`,vietnameseText:`Tháng trước, trường chúng tôi đã có một sự kiện **trồng** cây. Mỗi lớp phải trồng một **cây** trong vườn trường. Lớp tôi đã chọn một **cây** xoài giống. Chúng tôi rất **hào hứng** để bắt đầu.

Đầu tiên, chúng tôi **đào** một cái hố trên mặt đất. Sau đó chúng tôi đặt cây con vào và phủ **rễ** bằng đất. Chúng tôi **tưới** nước cho nó mỗi ngày. Giáo viên của chúng tôi nói chúng tôi cần **chăm sóc** cây trong cả năm.

Bây giờ cây đang **cao hơn** mỗi tuần. Nó có những chiếc **lá** xanh mới. Tôi cảm thấy **tự hào** khi nhìn vào nó. Cây cối cung cấp **oxy** cho chúng ta và làm sạch không khí. Trồng cây tốt cho **môi trường**. Tôi muốn trồng nhiều cây hơn trong khu phố của mình vào năm tới.`,vocabularyFocus:[{word:"planting",vi:"trồng",example:""},{word:"tree",vi:"cây",example:""},{word:"seedling",vi:"cây con",example:""},{word:"excited",vi:"hào hứng",example:""},{word:"dug",vi:"đào",example:""},{word:"roots",vi:"rễ",example:""},{word:"watered",vi:"tưới",example:""},{word:"oxygen",vi:"oxy",example:""}],phrases:[{en:"Each class had to plant a tree in the school garden.",vi:"Mỗi lớp phải trồng một cây trong vườn trường."},{en:"We dug a hole in the ground.",vi:"Chúng tôi đào một cái hố trên mặt đất."},{en:"We watered it every day.",vi:"Chúng tôi tưới nước cho nó mỗi ngày."},{en:"Trees give us oxygen and make the air clean.",vi:"Cây cối cung cấp oxy cho chúng ta và làm sạch không khí."},{en:"Planting trees is good for the environment.",vi:"Trồng cây tốt cho môi trường."}],comprehensionQuestions:[{question:"What kind of tree did the class plant?",options:["Mango","Banana","Coconut","Orange"],correct:0},{question:"Where did they plant the tree?",options:["At the park","In the school garden","At home","In the forest"],correct:1},{question:"What did they do first?",options:["Watered the tree","Dug a hole","Covered the roots","Added fertilizer"],correct:1},{question:"How long must the class take care of the tree?",options:["One month","Six months","One year","Two years"],correct:2},{question:"What do trees give us according to the story?",options:["Food and water","Oxygen and clean air","Wood and paper","Shade and fruit"],correct:1}],answers:[0,1,1,2,1],answerExplanationVi:"1. Lớp đã trồng cây xoài. 2. Họ trồng trong vườn trường. 3. Đầu tiên họ đào một cái hố. 4. Họ cần chăm sóc cây trong một năm. 5. Cây cối cung cấp oxy và làm sạch không khí.",discussionQuestions:["Bạn đã bao giờ trồng cây chưa? Bạn trồng cây gì?","Theo bạn, trồng cây có lợi ích gì cho môi trường?","Bạn muốn trồng thêm cây gì ở nhà hoặc trường học?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["Each class had to plant a tree in the school garden.","My class chose a mango seedling.","First, we dug a hole in the ground.","We watered it every day.","Planting trees is good for the environment."]},{id:"a2_17",level:"A2",topic:"family",title:"Family Dinner on Sunday",titleVi:"Bữa Tối Gia Đình Chủ Nhật",illustrationEmoji:"🍽️",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: bữa tối gia đình chủ nhật.",englishText:`Every Sunday evening, my family has a **special** dinner together. This is a **tradition** in our family. Everyone **gathers** around the table and shares stories about the week.

Last Sunday, my mother cooked many **dishes**. She made fried chicken, vegetable soup, and **stir-fried** morning glory. My father **grilled** some pork chops. I helped **set** the table and arrange the chopsticks. The food was **wonderful**.

During dinner, we **talked** about our week. I told them about my test results. My sister **shared** stories about her new friends. We also **planned** a trip to the beach next month. Family dinner is a **warm** and happy time. I think it is the best **moment** of the week.`,vietnameseText:`Mỗi tối Chủ Nhật, gia đình tôi có bữa tối **đặc biệt** cùng nhau. Đây là một **truyền thống** trong gia đình tôi. Mọi người **tụ họp** quanh bàn và chia sẻ những câu chuyện về tuần qua.

Chủ Nhật tuần trước, mẹ tôi đã nấu nhiều **món ăn**. Mẹ làm gà rán, canh rau củ và **rau** muống xào. Bố tôi **nướng** một ít sườn heo. Tôi đã giúp **dọn** bàn và sắp xếp đũa. Đồ ăn thật **tuyệt vời**.

Trong bữa tối, chúng tôi **nói chuyện** về tuần của mình. Tôi kể về kết quả bài kiểm tra của mình. Em gái tôi **chia sẻ** những câu chuyện về bạn mới. Chúng tôi cũng **lên kế hoạch** cho một chuyến đi biển vào tháng sau. Bữa tối gia đình là khoảng thời gian **ấm áp** và hạnh phúc. Tôi nghĩ đó là **khoảnh khắc** tuyệt vời nhất trong tuần.`,vocabularyFocus:[{word:"special",vi:"đặc biệt",example:""},{word:"tradition",vi:"truyền thống",example:""},{word:"gathers",vi:"tụ họp",example:""},{word:"dishes",vi:"món ăn",example:""},{word:"grilled",vi:"nướng",example:""},{word:"set",vi:"dọn bàn",example:""},{word:"talked",vi:"nói chuyện",example:""},{word:"shared",vi:"chia sẻ",example:""}],phrases:[{en:"Every Sunday evening, my family has a special dinner together.",vi:"Mỗi tối Chủ Nhật, gia đình tôi có bữa tối đặc biệt cùng nhau."},{en:"This is a tradition in our family.",vi:"Đây là một truyền thống trong gia đình tôi."},{en:"Everyone gathers around the table.",vi:"Mọi người tụ họp quanh bàn."},{en:"We talked about our week.",vi:"Chúng tôi nói chuyện về tuần của mình."},{en:"Family dinner is a warm and happy time.",vi:"Bữa tối gia đình là khoảng thời gian ấm áp và hạnh phúc."}],comprehensionQuestions:[{question:"When does the family have a special dinner?",options:["Saturday evening","Sunday evening","Friday evening","Monday evening"],correct:1},{question:"What did the mother cook last Sunday?",options:["Pho and spring rolls","Fried chicken and soup","Fish and rice","Noodles and dumplings"],correct:1},{question:"What did the father grill?",options:["Chicken","Fish","Pork chops","Beef"],correct:2},{question:"What did the writer share about at dinner?",options:["A story","Test results","A joke","A plan"],correct:1},{question:"What did the family plan for next month?",options:["A party","A trip to the beach","A picnic","A wedding"],correct:1}],answers:[1,1,2,1,1],answerExplanationVi:"1. Bữa tối đặc biệt diễn ra vào tối Chủ Nhật. 2. Mẹ nấu gà rán và canh rau củ. 3. Bố nướng sườn heo. 4. Người viết chia sẻ về kết quả bài kiểm tra. 5. Họ lên kế hoạch đi biển vào tháng sau.",discussionQuestions:["Gia đình bạn có bữa ăn chung thường xuyên không?","Theo bạn, bữa ăn gia đình quan trọng thế nào?","Bạn thường nói về điều gì trong bữa ăn gia đình?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["Every Sunday evening, my family has a special dinner together.","Everyone gathers around the table.","My mother cooked many dishes.","We talked about our week.","Family dinner is a warm and happy time."]},{id:"a2_18",level:"A2",topic:"travel",title:"A Day at the Museum",titleVi:"Một Ngày Ở Bảo Tàng",illustrationEmoji:"🏛️",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: một ngày ở bảo tàng.",englishText:`Last Sunday, my class visited the **Museum** of Ethnology. We went there with our **history** teacher. The museum was very big with many interesting **exhibits**.

We saw traditional **houses** of different ethnic groups in Vietnam. There was a long **stilt** house from the Central Highlands. We also saw colorful **costumes** and tools used by the people. Our teacher **explained** how each group lived and worked.

In the afternoon, we watched a **performance** of traditional music and dance. Some of my classmates **tried** to play the gongs. It was **fun**! I learned that Vietnam has 54 different ethnic **groups**. Each group has its own **customs** and traditions. I felt **proud** of our country's diversity.`,vietnameseText:`Chủ Nhật tuần trước, lớp tôi đã thăm **Bảo tàng** Dân tộc học. Chúng tôi đến đó cùng với giáo viên **lịch sử** của mình. Bảo tàng rất lớn với nhiều **triển lãm** thú vị.

Chúng tôi đã thấy những **ngôi nhà** truyền thống của các dân tộc khác nhau ở Việt Nam. Có một **nhà** sàn dài từ Tây Nguyên. Chúng tôi cũng thấy **trang phục** đầy màu sắc và công cụ được người dân sử dụng. Giáo viên của chúng tôi đã **giải thích** cách mỗi nhóm dân tộc sống và làm việc.

Buổi chiều, chúng tôi xem một buổi **biểu diễn** nhạc và múa truyền thống. Một số bạn cùng lớp đã **thử** chơi cồng chiêng. Thật là **vui**! Tôi đã học được rằng Việt Nam có 54 **dân tộc** khác nhau. Mỗi dân tộc có **phong tục** và truyền thống riêng. Tôi cảm thấy **tự hào** về sự đa dạng của đất nước chúng ta.`,vocabularyFocus:[{word:"Museum of Ethnology",vi:"Bảo tàng Dân tộc học",example:""},{word:"history",vi:"lịch sử",example:""},{word:"exhibits",vi:"triển lãm",example:""},{word:"houses",vi:"ngôi nhà",example:""},{word:"costumes",vi:"trang phục",example:""},{word:"explained",vi:"giải thích",example:""},{word:"performance",vi:"buổi biểu diễn",example:""},{word:"customs",vi:"phong tục",example:""}],phrases:[{en:"My class visited the Museum of Ethnology.",vi:"Lớp tôi đã thăm Bảo tàng Dân tộc học."},{en:"The museum was very big with many interesting exhibits.",vi:"Bảo tàng rất lớn với nhiều triển lãm thú vị."},{en:"We saw traditional houses of different ethnic groups.",vi:"Chúng tôi đã thấy những ngôi nhà truyền thống của các dân tộc khác nhau."},{en:"Vietnam has 54 different ethnic groups.",vi:"Việt Nam có 54 dân tộc khác nhau."},{en:"I felt proud of our country diversity.",vi:"Tôi cảm thấy tự hào về sự đa dạng của đất nước chúng ta."}],comprehensionQuestions:[{question:"Which museum did the class visit?",options:["History Museum","Museum of Ethnology","Art Museum","Army Museum"],correct:1},{question:"What did they see from the Central Highlands?",options:["A boat","A stilt house","A temple","A statue"],correct:1},{question:"Who explained how each group lived?",options:["A guide","The teacher","A friend","A video"],correct:1},{question:"What did some classmates try to play?",options:["Drums","Gongs","Flutes","Guitars"],correct:1},{question:"How many ethnic groups does Vietnam have?",options:["34","44","54","64"],correct:2}],answers:[1,1,1,1,2],answerExplanationVi:"1. Lớp đã thăm Bảo tàng Dân tộc học. 2. Họ thấy nhà sàn từ Tây Nguyên. 3. Giáo viên đã giải thích về các dân tộc. 4. Một số bạn đã thử chơi cồng chiêng. 5. Việt Nam có 54 dân tộc.",discussionQuestions:["Bạn đã từng đến bảo tàng nào chưa? Ấn tượng của bạn thế nào?","Theo bạn, học lịch sử qua bảo tàng có thú vị không?","Bạn muốn giới thiệu bảo tàng nào cho bạn bè quốc tế?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My class visited the Museum of Ethnology.","The museum was very big with many interesting exhibits.","We saw traditional houses of different ethnic groups.","Vietnam has 54 different ethnic groups.","I felt proud of our country diversity."]},{id:"a2_19",level:"A2",topic:"food",title:"Trying New Fruits",titleVi:"Thử Trái Cây Mới",illustrationEmoji:"🥭",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: thử trái cây mới.",englishText:`Last week, my mother bought some **fruits** I had never tried before. She brought them from the **market**. I was **curious** about their taste and smell.

The first fruit was **durian**. It has a very strong **smell**. At first, I did not like the smell. But when I **tasted** it, the flavor was sweet and **creamy**. Now I understand why many people love it.

We also tried **dragon** fruit and mangosteen. Dragon fruit looks **beautiful** with its pink skin and white flesh. Mangosteen has a sweet and sour **taste**. I loved it **immediately**. My mother was happy because I am now more **open** to trying new foods. I want to **discover** more fruits from different regions of Vietnam.`,vietnameseText:`Tuần trước, mẹ tôi đã mua một số **trái cây** mà tôi chưa từng thử trước đây. Mẹ mang chúng từ **chợ** về. Tôi rất **tò mò** về mùi vị của chúng.

Loại trái cây đầu tiên là **sầu riêng**. Nó có mùi rất **nồng**. Lúc đầu, tôi không thích mùi đó. Nhưng khi tôi **nếm thử**, vị của nó ngọt và **béo**. Bây giờ tôi hiểu tại sao nhiều người yêu thích nó.

Chúng tôi cũng đã thử **thanh** long và măng cụt. Thanh long trông rất **đẹp** với vỏ hồng và ruột trắng. Măng cụt có **vị** chua ngọt. Tôi đã thích nó **ngay lập tức**. Mẹ tôi rất vui vì bây giờ tôi **cởi mở** hơn với việc thử đồ ăn mới. Tôi muốn **khám phá** thêm nhiều loại trái cây từ các vùng khác nhau của Việt Nam.`,vocabularyFocus:[{word:"fruits",vi:"trái cây",example:""},{word:"market",vi:"chợ",example:""},{word:"curious",vi:"tò mò",example:""},{word:"durian",vi:"sầu riêng",example:""},{word:"smell",vi:"mùi",example:""},{word:"tasted",vi:"nếm thử",example:""},{word:"creamy",vi:"béo ngậy",example:""},{word:"discover",vi:"khám phá",example:""}],phrases:[{en:"My mother bought some fruits I had never tried before.",vi:"Mẹ tôi đã mua một số trái cây mà tôi chưa từng thử trước đây."},{en:"The first fruit was durian.",vi:"Loại trái cây đầu tiên là sầu riêng."},{en:"It has a very strong smell.",vi:"Nó có mùi rất nồng."},{en:"The flavor was sweet and creamy.",vi:"Vị của nó ngọt và béo."},{en:"I want to discover more fruits from different regions.",vi:"Tôi muốn khám phá thêm nhiều loại trái cây từ các vùng khác nhau."}],comprehensionQuestions:[{question:"Where did mother buy the fruits?",options:["Supermarket","Market","Farm","Shop"],correct:1},{question:"What was the first fruit the writer tried?",options:["Dragon fruit","Mangosteen","Durian","Rambutan"],correct:2},{question:"How did the writer feel about the durian smell at first?",options:["Liked it","Did not like it","Did not notice","Loved it"],correct:1},{question:"What does dragon fruit look like?",options:["Yellow skin","Pink skin","Green skin","Purple skin"],correct:1},{question:"How did the writer feel about mangosteen?",options:["Did not like it","Loved it immediately","Found it sour","Found it bitter"],correct:1}],answers:[1,2,1,1,1],answerExplanationVi:"1. Mẹ mua trái cây từ chợ. 2. Loại đầu tiên là sầu riêng. 3. Lúc đầu người viết không thích mùi sầu riêng. 4. Thanh long có vỏ hồng. 5. Người viết đã thích măng cụt ngay lập tức.",discussionQuestions:["Bạn có thích thử trái cây mới không? Loại nào bạn yêu thích?","Bạn có bao giờ ăn sầu riêng chưa? Bạn nghĩ thế nào về nó?","Theo bạn, tại sao nên thử những món ăn mới?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My mother bought some fruits I had never tried before.","I was curious about their taste.","The first fruit was durian.","The flavor was sweet and creamy.","I want to discover more fruits from different regions."]},{id:"a2_20",level:"A2",topic:"school",title:"Preparing for Exams",titleVi:"Chuẩn Bị Cho Kỳ Thi",illustrationEmoji:"📝",estimatedMinutes:5,xpReward:50,summaryVi:"Câu chuyện A2: chuẩn bị cho kỳ thi.",englishText:`My final **exams** are coming next month. I have been **studying** very hard to get good results. I made a **study** schedule to organize my time **effectively**.

Every day, I **review** my notes for two hours after school. I focus on the **subjects** that I am weak at, such as math and English. I also **practice** with past exam papers. My friend and I form a study **group** every Saturday.

I try to eat healthy food and get enough **sleep** to stay healthy. My mother **reminds** me to take breaks between study sessions. I feel **nervous** but also confident. I believe that hard work will **pay off**. After the exams, I plan to relax and **travel** with my family.`,vietnameseText:`**Kỳ thi** cuối kỳ của tôi sắp đến vào tháng sau. Tôi đã **học** rất chăm chỉ để đạt kết quả tốt. Tôi đã lập một lịch trình **học tập** để sắp xếp thời gian một cách **hiệu quả**.

Mỗi ngày, tôi **ôn lại** bài ghi chép trong hai giờ sau giờ học. Tôi tập trung vào những **môn học** mà tôi yếu, như toán và tiếng Anh. Tôi cũng **luyện tập** với các đề thi cũ. Bạn tôi và tôi thành lập một nhóm **học tập** vào mỗi thứ Bảy.

Tôi cố gắng ăn uống lành mạnh và ngủ đủ **giấc** để giữ sức khỏe. Mẹ tôi **nhắc nhở** tôi nghỉ giải lao giữa các buổi học. Tôi cảm thấy **lo lắng** nhưng cũng tự tin. Tôi tin rằng làm việc chăm chỉ sẽ **được đền đáp**. Sau kỳ thi, tôi dự định thư giãn và **đi du lịch** cùng gia đình.`,vocabularyFocus:[{word:"exams",vi:"kỳ thi",example:""},{word:"studying",vi:"học tập",example:""},{word:"study",vi:"học",example:""},{word:"effectively",vi:"hiệu quả",example:""},{word:"review",vi:"ôn lại",example:""},{word:"subjects",vi:"môn học",example:""},{word:"practice",vi:"luyện tập",example:""},{word:"pay off",vi:"được đền đáp",example:""}],phrases:[{en:"My final exams are coming next month.",vi:"Kỳ thi cuối kỳ của tôi sắp đến vào tháng sau."},{en:"I have been studying very hard to get good results.",vi:"Tôi đã học rất chăm chỉ để đạt kết quả tốt."},{en:"I made a study schedule to organize my time.",vi:"Tôi đã lập một lịch trình học tập để sắp xếp thời gian."},{en:"I focus on the subjects that I am weak at.",vi:"Tôi tập trung vào những môn học mà tôi yếu."},{en:"I believe that hard work will pay off.",vi:"Tôi tin rằng làm việc chăm chỉ sẽ được đền đáp."}],comprehensionQuestions:[{question:"When are the final exams?",options:["Next week","Next month","In two months","Next year"],correct:1},{question:"How many hours does the writer study after school?",options:["One hour","Two hours","Three hours","Four hours"],correct:1},{question:"Which subjects does the writer focus on?",options:["Science and literature","Math and English","History and geography","Art and music"],correct:1},{question:"What does the writer do every Saturday?",options:["Goes to the library","Joins a study group","Visits a museum","Plays sports"],correct:1},{question:"What does the writer plan to do after exams?",options:["Study more","Relax and travel","Find a job","Move to a new city"],correct:1}],answers:[1,1,1,1,1],answerExplanationVi:"1. Kỳ thi cuối kỳ vào tháng sau. 2. Người viết học hai giờ mỗi ngày sau giờ học. 3. Người viết tập trung vào toán và tiếng Anh. 4. Người viết tham gia nhóm học tập vào thứ Bảy. 5. Sau kỳ thi người viết dự định thư giãn và đi du lịch.",discussionQuestions:["Bạn có lo lắng về kỳ thi không? Bạn chuẩn bị thế nào?","Bạn có bí quyết học tập hiệu quả nào không?","Sau kỳ thi, bạn thường làm gì để thư giãn?"],grammarFocus:{point:"Simple Past Tense (Thì Quá Khứ Đơn)",explanation:'Thì quá khứ đơn dùng để kể về sự việc đã xảy ra và kết thúc trong quá khứ. Động từ thêm "ed" (regular) hoặc dạng bất quy tắc (irregular). Ví dụ: "visited" (đã thăm), "went" (đã đi).'},shadowingSentences:["My final exams are coming next month.","I made a study schedule to organize my time.","I review my notes for two hours after school.","I focus on the subjects that I am weak at.","I believe that hard work will pay off."]}];export{t as s};
